.ds {
  --ds-base-text:var(--p-ink,#2c333d);
  --ds-base-bg:var(--p-bg,#ffffff);
  --ds-base-text-md:var(--p-text-md,16px);
  --ds-base-font:var(--p-font,Pretendard, sans-serif);
  --ds-base-focus:var(--p-highlight,#6153b5);
  --ds-base-text-sm:var(--p-text-sm,13px);
  --ds-base-space-3:var(--p-space-sm,12px);
  --ds-base-muted:var(--p-muted,#59636f);
  --ds-base-border:var(--p-line,#c2cad5);
  --ds-base-radius:var(--p-radius,24px);
  --ds-base-surface:var(--p-surface,#f1f3f6);
  --ds-base-shadow:var(--p-shadow,6px 7px 16px #bbc4d166, -5px -5px 14px #ffffffed);
  --ds-base-edge:var(--p-edge,#ffffff);
  --ds-base-inset:var(--p-inset,inset 3px 3px 6px #b7c1cf55, inset -3px -3px 6px #ffffffd9);
  --ds-base-high:var(--p-high,#fafbfc);
  --ds-base-glass-shadow:var(--p-glass-shadow,0 8px 24px #38465e12);
  --ds-base-glass:var(--p-glass,#f6f8fbe8);
}
.ds {
  color:var(--ds-base-text); background:var(--ds-base-bg); font:var(--ds-base-text-md)/1.5 var(--ds-base-font);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:3px solid var(--ds-base-focus); outline-offset:3px; }
.ds .ui-icon { display:inline-block; width:20px; height:20px; flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--ds-base-text-sm); margin-top:var(--ds-base-space-3); min-height:20px; color:var(--ds-base-muted); }
.ds .ds-surface { border:1px solid var(--ds-base-border); border-radius:var(--ds-base-radius); background:var(--ds-base-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--ds-base-shadow); border-color:var(--ds-base-edge); }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--ds-base-inset); background:var(--ds-base-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--ds-base-high); box-shadow:var(--ds-base-glass-shadow); }
@supports (backdrop-filter:blur(16px)) { .ds .ds-surface[data-material="glass"] { background:var(--ds-base-glass); backdrop-filter:blur(16px); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--ds-base-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }

.ds {
  --ds-template-space-8:var(--p-space-xl,32px);
  --ds-template-space-2:var(--p-space-xs,8px);
  --ds-template-text-sm:var(--p-text-sm,13px);
  --ds-template-muted:var(--p-muted,#59636f);
  --ds-template-radius:var(--p-radius,24px);
  --ds-template-soft:var(--p-soft,#d3e8de);
  --ds-template-space-6:var(--p-space-lg,24px);
  --ds-template-border:var(--p-line,#c2cad5);
  --ds-template-accent:var(--p-accent,#303b48);
  --ds-template-on-accent:var(--p-on-accent,#ffffff);
  --ds-template-high:var(--p-high,#fafbfc);
  --ds-template-text:var(--p-ink,#2c333d);
  --ds-template-display-font:var(--p-display-font,Outfit, Pretendard, sans-serif);
  --ds-template-space-4:var(--p-space-md,16px);
  --ds-template-surface:var(--p-surface,#f1f3f6);
  --ds-template-control-border:var(--p-control-border,#7b8592);
}
.ds .ds-page { max-width:1080px; margin-inline:auto; }
.ds .ds-page-header { display:flex; justify-content:space-between; align-items:center; gap:16px; margin-bottom:var(--ds-template-space-8); }
.ds .ds-page-header h2 { font-size:32px; font-weight:650; letter-spacing:-.04em; margin-top:var(--ds-template-space-2); }
.ds .ds-eyebrow { font-size:var(--ds-template-text-sm); color:var(--ds-template-muted); }
.ds .ds-page > .ds-bottom-nav { margin:var(--ds-template-space-8) auto 0; max-width:480px; }
/* Looks: how the screen opens. Each look also brings its own bottom bar shape from the markup. */
.ds .ds-page[data-look="hero"] .ds-page-header { align-items:flex-end; padding:28px 20px 20px; border-radius:var(--ds-template-radius); background:var(--ds-template-soft); }
.ds .ds-page[data-look="hero"] .ds-page-header h2 { font-size:40px; line-height:1.1; }
.ds .ds-page[data-look="appbar"] .ds-page-header { position:relative; justify-content:center; padding:4px 64px 16px; margin-bottom:var(--ds-template-space-6); border-bottom:1px solid var(--ds-template-border); text-align:center; }
.ds .ds-page[data-look="appbar"] .ds-page-header h2 { margin-top:0; font-size:20px; letter-spacing:-.02em; }
.ds .ds-page[data-look="appbar"] .ds-page-header > .ds-badge { position:absolute; right:0; top:50%; translate:0 -60%; }
.ds .ds-page[data-look="sheet"] .ds-page-header { align-items:flex-start; margin-bottom:0; padding:24px 20px 64px; border-radius:var(--ds-template-radius) var(--ds-template-radius) 0 0; background:var(--ds-template-accent); color:var(--ds-template-on-accent); }
.ds .ds-page[data-look="sheet"] .ds-page-header .ds-eyebrow { color:color-mix(in oklab, var(--ds-template-on-accent) 74%, transparent); }
.ds .ds-page[data-look="sheet"] .ds-page-header + * { position:relative; margin-top:-32px; padding:24px 20px; border-radius:24px 24px 0 0; background:var(--ds-template-high); }
.ds .ds-page[data-look="magazine"] .ds-page-header { align-items:flex-end; padding-bottom:16px; border-bottom:2px solid var(--ds-template-text); }
.ds .ds-page[data-look="magazine"] .ds-page-header h2 { font:700 48px/1.05 var(--ds-template-display-font); letter-spacing:-.05em; }
.ds .ds-page[data-look="dashboard"] .ds-page-header { margin-bottom:var(--ds-template-space-4); }
.ds .ds-page-stats { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:8px; margin:0 0 var(--ds-template-space-6); padding:0; list-style:none; }
.ds .ds-page-stats li { display:grid; gap:2px; padding:12px; border:1px solid var(--ds-template-border); border-radius:16px; background:var(--ds-template-surface); }
.ds .ds-page-stats strong { font:700 22px/1.2 var(--ds-template-display-font); letter-spacing:-.03em; }
.ds .ds-page-stats span { font-size:12px; color:var(--ds-template-muted); }
.ds .ds-template-slot { min-height:160px; display:grid; place-items:center; padding:var(--ds-template-space-6); border:1px dashed var(--ds-template-control-border); border-radius:var(--ds-template-radius); color:var(--ds-template-muted); font-size:14px; }

.ds {
  --ds-badge-border:var(--p-line,#c2cad5);
  --ds-badge-soft:var(--p-soft,#d3e8de);
  --ds-badge-text:var(--p-ink,#2c333d);
  --ds-badge-success-soft:var(--p-success-soft,#e5f2eb);
  --ds-badge-success-line:var(--p-success-line,#8fb8a5);
  --ds-badge-success:var(--p-success,#26614f);
  --ds-badge-error-soft:var(--p-error-soft,#f9e8e9);
  --ds-badge-error-line:var(--p-error-line,#d4a2a8);
  --ds-badge-error:var(--p-error,#a3313e);
  --ds-badge-warning-soft:var(--p-warning-soft,#f6efd9);
  --ds-badge-warning-line:var(--p-warning-line,#b9a16f);
  --ds-badge-warning:var(--p-warning,#805719);
  --ds-badge-accent:var(--p-accent,#303b48);
  --ds-badge-on-accent:var(--p-on-accent,#ffffff);
  --ds-badge-bg:var(--p-bg,#ffffff);
  --ds-badge-raised:var(--p-raised,3px 4px 8px #b9c3d066, -3px -3px 8px #ffffffed);
}
.ds .ds-badge { display:inline-flex; align-items:center; width:fit-content; padding:4px 10px; border:1px solid var(--ds-badge-border); border-radius:99px; background:var(--ds-badge-soft); color:var(--ds-badge-text); font-size:12px; line-height:1.5; font-weight:600; }
.ds .ds-badge[data-tone="success"] { background:var(--ds-badge-success-soft); border-color:var(--ds-badge-success-line); color:var(--ds-badge-success); }
.ds .ds-badge[data-tone="error"] { background:var(--ds-badge-error-soft); border-color:var(--ds-badge-error-line); color:var(--ds-badge-error); }
.ds .ds-badge[data-tone="warning"] { background:var(--ds-badge-warning-soft); border-color:var(--ds-badge-warning-line); color:var(--ds-badge-warning); }
/* looks: tone keeps the color, look changes the shape */
.ds .ds-badge[data-look="outline"] { background:transparent; border-color:currentColor; }
.ds .ds-badge[data-look="solid"] { background:var(--ds-badge-accent); border-color:var(--ds-badge-accent); color:var(--ds-badge-on-accent); }
.ds .ds-badge[data-look="solid"][data-tone="success"] { background:var(--ds-badge-success); border-color:var(--ds-badge-success); }
.ds .ds-badge[data-look="solid"][data-tone="error"] { background:var(--ds-badge-error); border-color:var(--ds-badge-error); }
.ds .ds-badge[data-look="solid"][data-tone="warning"] { background:var(--ds-badge-warning); border-color:var(--ds-badge-warning); }
.ds .ds-badge[data-look="dot"] { gap:6px; background:var(--ds-badge-bg); }
.ds .ds-badge[data-look="dot"]::before { content:''; width:8px; height:8px; border-radius:50%; background:currentColor; }
.ds .ds-badge[data-look="square"] { border-radius:6px; }
.ds .ds-badge[data-look="tag"] { padding-left:18px; border-color:transparent; border-radius:0 6px 6px 0; clip-path:polygon(10px 0,100% 0,100% 100%,10px 100%,0 50%); }
.ds .ds-badge[data-look="raised"] { background:var(--ds-badge-bg); border-color:transparent; box-shadow:var(--ds-badge-raised); }

.ds {
  --ds-search-module-space-3:var(--p-space-sm,12px);
  --ds-search-module-text-sm:var(--p-text-sm,13px);
  --ds-search-module-muted:var(--p-muted,#59636f);
  --ds-search-module-space-6:var(--p-space-lg,24px);
  --ds-search-module-space-4:var(--p-space-md,16px);
  --ds-search-module-space-8:var(--p-space-xl,32px);
  --ds-search-module-control-border:var(--p-control-border,#7b8592);
  --ds-search-module-radius:var(--p-radius,24px);
  --ds-search-module-border:var(--p-line,#c2cad5);
  --ds-search-module-surface:var(--p-surface,#f1f3f6);
  --ds-search-module-text-lg:var(--p-text-lg,24px);
  --ds-search-module-success:var(--p-success,#26614f);
  --ds-search-module-bg:var(--p-bg,#ffffff);
  --ds-search-module-inset:var(--p-inset,inset 3px 3px 6px #b7c1cf55, inset -3px -3px 6px #ffffffd9);
  --ds-search-module-accent:var(--p-accent,#303b48);
  --ds-search-module-on-accent:var(--p-on-accent,#ffffff);
  --ds-search-module-focus:var(--p-highlight,#6153b5);
  --ds-search-module-high:var(--p-high,#fafbfc);
  --ds-search-module-shadow:var(--p-shadow,6px 7px 16px #bbc4d166, -5px -5px 14px #ffffffed);
  --ds-search-module-soft:var(--p-soft,#d3e8de);
}
.ds .ds-search-module { container-type:inline-size; }
.ds .ds-search-form { display:grid; grid-template-columns:minmax(0,1fr) minmax(90px,.3fr) auto; align-items:end; gap:var(--ds-search-module-space-3); }
.ds .ds-result-count { font-size:var(--ds-search-module-text-sm); color:var(--ds-search-module-muted); margin-block:var(--ds-search-module-space-6) var(--ds-search-module-space-4); }
.ds .ds-results { display:grid; grid-template-columns:repeat(auto-fit,minmax(min(100%,210px),1fr)); gap:var(--ds-search-module-space-6); }
.ds .ds-empty { padding:var(--ds-search-module-space-8); text-align:center; border:1px dashed var(--ds-search-module-control-border); border-radius:var(--ds-search-module-radius); }
.ds .ds-empty .ds-button { margin-top:var(--ds-search-module-space-4); }
.ds .ds-record-detail { padding:var(--ds-search-module-space-6); border:1px solid var(--ds-search-module-border); border-radius:var(--ds-search-module-radius); background:var(--ds-search-module-surface); }
.ds .ds-record-detail h3 { font-size:var(--ds-search-module-text-lg); font-weight:650; }
.ds .ds-record-detail p { margin-top:var(--ds-search-module-space-3); color:var(--ds-search-module-muted); }
.ds .ds-record-detail > div { display:flex; flex-wrap:wrap; gap:var(--ds-search-module-space-3); margin-top:var(--ds-search-module-space-6); }
.ds .ds-record-detail [aria-pressed="true"] { background:var(--ds-search-module-success); border-color:var(--ds-search-module-success); }
@media(max-width:580px) { .ds .ds-search-form { grid-template-columns:minmax(0,1fr) auto; } .ds .ds-search-form > .ds-field { grid-column:1/-1; } }
@container(max-width:580px) { .ds .ds-search-form { grid-template-columns:minmax(0,1fr) auto; } .ds .ds-search-form > .ds-field { grid-column:1/-1; } }
/* Looks. Labels hidden by a look stay in the page for screen readers. */
.ds .ds-search-module[data-look="pill"] :is(.ds-field > label,.ds-select-field > span),.ds .ds-chip-group > legend,.ds .ds-chip input { position:absolute; width:1px; height:1px; overflow:hidden; clip-path:inset(50%); white-space:nowrap; }
/* 02 pill: query, status and button share one rounded bar */
.ds .ds-search-module[data-look="pill"] .ds-search-form { grid-template-columns:minmax(0,1fr) auto auto; align-items:center; gap:4px; padding:4px 4px 4px 12px; border:1px solid var(--ds-search-module-control-border); border-radius:999px; background:var(--ds-search-module-bg); box-shadow:var(--ds-search-module-inset); }
.ds .ds-search-module[data-look="pill"] .ds-search-form > .ds-field { grid-column:auto; }
.ds .ds-search-module[data-look="pill"] .ds-search-form .ds-input { border:0; background:transparent; box-shadow:none; }
.ds .ds-search-module[data-look="pill"] .ds-search-form select.ds-input { width:auto; padding-inline:12px 8px; border-left:1px solid var(--ds-search-module-border); border-radius:0; }
.ds .ds-search-module[data-look="pill"] .ds-search-form > .ds-button { border-radius:999px; }
@container(max-width:420px) { .ds .ds-search-module[data-look="pill"] .ds-search-form > .ds-button { gap:0; padding-inline:12px; font-size:0; } }
/* 03 chips: status as a row of chips under the query */
.ds .ds-search-module[data-look="chips"] .ds-search-form { grid-template-columns:minmax(0,1fr) auto; }
.ds .ds-search-module[data-look="chips"] .ds-search-form > .ds-field { grid-column:auto; }
.ds .ds-chip-group { grid-column:1/-1; order:3; display:flex; flex-wrap:wrap; gap:8px; min-width:0; margin:0; padding:0; border:0; }
.ds .ds-chip { position:relative; display:inline-flex; align-items:center; gap:6px; min-height:44px; padding:0 16px; border:1px solid var(--ds-search-module-control-border); border-radius:999px; background:var(--ds-search-module-bg); font-size:14px; cursor:pointer; }
.ds .ds-chip:has(:checked) { border-color:var(--ds-search-module-accent); background:var(--ds-search-module-accent); color:var(--ds-search-module-on-accent); font-weight:650; }
.ds .ds-chip:has(:checked)::before { content:'✓'; font-weight:700; }
.ds .ds-chip:has(:focus-visible) { outline:3px solid var(--ds-search-module-focus); outline-offset:3px; }
/* 04 list and 05 command: results as rows instead of tiles */
.ds .ds-search-module:is([data-look="list"],[data-look="command"]) .ds-results { grid-template-columns:minmax(0,1fr); gap:0; }
.ds .ds-search-module:is([data-look="list"],[data-look="command"]) .ds-card { flex-flow:row wrap; align-items:center; border:0; border-radius:0; background:transparent; box-shadow:none; }
.ds .ds-search-module:is([data-look="list"],[data-look="command"]) .ds-card-body { flex:1 1 160px; padding:14px 0; }
.ds .ds-search-module:is([data-look="list"],[data-look="command"]) .ds-card h3 { margin-top:4px; font-size:17px; }
.ds .ds-search-module:is([data-look="list"],[data-look="command"]) .ds-divider { display:none; }
.ds .ds-search-module:is([data-look="list"],[data-look="command"]) .ds-card-actions { padding:8px 0 8px 12px; }
.ds .ds-search-module[data-look="list"] .ds-results { border-top:1px solid var(--ds-search-module-border); }
.ds .ds-search-module[data-look="list"] .ds-card { border-bottom:1px solid var(--ds-search-module-border); }
.ds .ds-search-module[data-look="command"] { padding:var(--ds-search-module-space-4); border:1px solid var(--ds-search-module-border); border-radius:20px; background:var(--ds-search-module-high); box-shadow:var(--ds-search-module-shadow); }
.ds .ds-search-module[data-look="command"] .ds-search-form .ds-input:not(select) { min-height:56px; font-size:17px; }
.ds .ds-search-module[data-look="command"] .ds-results { gap:4px; }
.ds .ds-search-module[data-look="command"] .ds-card { padding-inline:14px; border-radius:12px; }
.ds .ds-search-module[data-look="command"] [data-result]:not([hidden]) ~ [data-result] .ds-card { background:transparent; box-shadow:none; }
.ds .ds-search-module[data-look="command"] [data-result]:not([hidden]) .ds-card { background:var(--ds-search-module-soft); box-shadow:inset 3px 0 0 var(--ds-search-module-accent); }
/* 07 feature: the first result spans the row with a bigger title */
.ds .ds-search-module[data-look="feature"] .ds-results > :first-child { grid-column:1/-1; }
.ds .ds-search-module[data-look="feature"] .ds-results > :first-child h3 { font-size:26px; line-height:1.3; }

.ds {
  --ds-field-space-2:var(--p-space-xs,8px);
  --ds-field-text-sm:var(--p-text-sm,13px);
  --ds-field-muted:var(--p-muted,#59636f);
  --ds-field-error:var(--p-error,#a3313e);
  --ds-field-success:var(--p-success,#26614f);
  --ds-field-focus:var(--p-highlight,#6153b5);
  --ds-field-space-3:var(--p-space-sm,12px);
  --ds-field-space-4:var(--p-space-md,16px);
  --ds-field-border:var(--p-line,#c2cad5);
  --ds-field-radius:var(--p-radius,24px);
  --ds-field-surface:var(--p-surface,#f1f3f6);
}
.ds .ds-field,.ds .ds-select-field { display:grid; gap:var(--ds-field-space-2); min-width:0; font-size:14px; }
.ds .ds-field > label,.ds .ds-select-field > span { font-weight:600; }
.ds .ds-help { font-size:var(--ds-field-text-sm); color:var(--ds-field-muted); line-height:1.5; }
.ds .ds-field[data-state="error"] .ds-help { color:var(--ds-field-error); }
.ds .ds-field[data-state="error"] .ds-help::before { content:'!'; display:inline-grid; place-items:center; width:14px; height:14px; font-size:11px; border:1px solid currentColor; border-radius:50%; margin-right:5px; }
.ds .ds-field[data-state="success"] .ds-help { color:var(--ds-field-success); }
.ds .ds-field[data-state="success"] .ds-help::before { content:'✓'; margin-right:5px; }
.ds .ds-field[data-state="success"] .ds-input { border-color:var(--ds-field-success); }
.ds .ds-field[data-state="focus"] .ds-input { outline:3px solid var(--ds-field-focus); outline-offset:3px; }
/* looks: layout of label, input and help; input shapes come from the input part */
.ds .ds-field[data-look="inline"] { grid-template-columns:96px minmax(0,1fr); align-items:center; column-gap:var(--ds-field-space-3); }
.ds .ds-field[data-look="inline"] > .ds-help { grid-column:2; }
.ds .ds-field[data-look="filled"] { position:relative; }
.ds .ds-field[data-look="filled"] > label { position:absolute; z-index:1; top:7px; left:14px; color:var(--ds-field-muted); font-size:12px; line-height:1.4; pointer-events:none; }
.ds .ds-field[data-look="filled"] .ds-input { min-height:58px; padding-top:25px; padding-bottom:7px; }
.ds .ds-field[data-look="card"] { padding:var(--ds-field-space-4); border:1px solid var(--ds-field-border); border-radius:var(--ds-field-radius); background:var(--ds-field-surface); }
.ds .ds-field[data-look][data-state="success"] .ds-input { border-color:var(--ds-field-success); }

.ds {
  --ds-input-control-border:var(--p-control-border,#7b8592);
  --ds-input-control-radius:var(--p-control-radius,16px);
  --ds-input-bg:var(--p-bg,#ffffff);
  --ds-input-inset:var(--p-inset,inset 3px 3px 6px #b7c1cf55, inset -3px -3px 6px #ffffffd9);
  --ds-input-text:var(--p-ink,#2c333d);
  --ds-input-muted:var(--p-muted,#59636f);
  --ds-input-disabled:var(--p-disabled,#dce1e8);
  --ds-input-border:var(--p-line,#c2cad5);
  --ds-input-error:var(--p-error,#a3313e);
  --ds-input-space-2:var(--p-space-xs,8px);
  --ds-input-surface:var(--p-surface,#f1f3f6);
  --ds-input-radius:var(--p-radius,24px);
  --ds-input-soft:var(--p-soft,#d3e8de);
  --ds-input-high:var(--p-high,#fafbfc);
