  const filtered = records.filter(item => filter.query.toLocaleLowerCase().split(/\s+/).every(term => `${item.title} ${item.description}`.toLocaleLowerCase().includes(term)) && (filter.status === 'all' || item.tag === filter.status));
  useEffect(() => { if (selected) detail.current?.focus(); else opener.current?.focus(); }, [selected]);
  function search(event) { event.preventDefault(); const data = new FormData(event.currentTarget); setFilter({ query: String(data.get('query')).trim(), status: data.get('status') }); }
  function open(item, event) { opener.current = event.currentTarget; setSelected(item); }
  function close() { setSelected(null); }
  async function save() {
    const record = selected;
    if (!record || pending.current.has(record.id)) return;
    pending.current.add(record.id);
    setPendingIds([...pending.current]);
    setMessages(old => ({ ...old, [record.id]: '' }));
    try {
      await onSave?.(record);
      setSaved(old => [...new Set([...old, record.id])]);
      setMessages(old => ({ ...old, [record.id]: '보관했어요.' }));
    } catch {
      setMessages(old => ({ ...old, [record.id]: '보관하지 못했어요. 다시 시도해 주세요.' }));
    } finally {
      pending.current.delete(record.id);
      setPendingIds([...pending.current]);
    }
  }
  const pick = event => setFilter({ query: form.current.elements.query.value.trim(), status: event.target.value });
  const cardLook = index => look === 'media' || (look === 'feature' && index === 0) ? 'media' : 'raised';
  const status = look === 'chips'
    ? <fieldset className="ds-chip-group"><legend>상태</legend>{statuses.map(([value, label]) => <label key={value} className="ds-chip"><input type="radio" name="status" value={value} defaultChecked={value === 'all'} onChange={pick} /><span>{label}</span></label>)}</fieldset>
    : <label className="ds-select-field" htmlFor={`${id}-status`}><span>상태</span><select id={`${id}-status`} className="ds-input" name="status" onChange={pick}>{statuses.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label>;
  return <section className="ds-search-module" data-look={look} aria-label="컬렉션 검색"><div hidden={!!selected}><form ref={form} className="ds-search-form" onSubmit={search}><Field label="컬렉션 검색" name="query" placeholder="이름으로 검색" />{status}<Button type="submit">검색</Button></form><p className="ds-result-count" role="status">{filtered.length}개의 컬렉션</p><div className="ds-results">{filtered.map((item, index) => <div key={item.id}><Card look={cardLook(index)}><CardBody><Badge>{item.tag}</Badge><CardTitle>{item.title}</CardTitle><CardDescription>{item.description}</CardDescription></CardBody><CardActions><Button variant="outline" size="sm" onClick={event => open(item, event)}>열기</Button></CardActions></Card></div>)}</div>{!filtered.length && <div className="ds-empty"><p>일치하는 컬렉션이 없어요.</p><Button variant="outline" onClick={() => { form.current.reset(); setFilter({ query: '', status: 'all' }); form.current.elements.query.focus(); }}>전체 보기</Button></div>}</div>{selected && <section ref={detail} className="ds-record-detail" aria-label="컬렉션 상세" tabIndex={-1}><h3>{selected.title}</h3><p>{selected.description}</p><div><Button variant="outline" onClick={close}>목록으로</Button><Button loading={busy} aria-pressed={saved.includes(selected.id)} onClick={save}>{saved.includes(selected.id) ? '보관됨' : '컬렉션에 보관'}</Button></div><p role="status">{message}</p></section>}</section>;
}

'use client';
import React, { useId } from 'react';
import { Input } from './input.jsx';
export function FieldLabel({ htmlFor, children, ...props }) { return <label {...props} htmlFor={htmlFor}>{children}</label>; }
export function FieldDescription({ id, children, ...props }) { return <p {...props} className="ds-help" id={id}>{children}</p>; }
export function Field({ id: suppliedId, look, label, help, error, state, children, ...props }) {
  const generatedId = useId(); const id = suppliedId || generatedId;
  const description = error || help;
  const inputProps = { ...props, id, 'aria-invalid': error ? true : undefined, 'aria-describedby': [props['aria-describedby'], description ? `${id}-help` : ''].filter(Boolean).join(' ') || undefined };
  return <div className="ds-field" data-look={look} data-state={error ? 'error' : props.disabled ? 'disabled' : state}>
    <FieldLabel htmlFor={id}>{label}</FieldLabel>
    {children ? children(inputProps) : <Input {...inputProps} />}
    {description && <FieldDescription id={`${id}-help`}>{description}</FieldDescription>}
  </div>;
}

import React from 'react';
export function Button({ children, look, variant = 'primary', size = 'md', loading = false, disabled, className = '', type = 'button', ...props }) {
  return <button {...props} type={type} className={`ds-button ${className}`} data-variant={variant} data-size={size} data-look={look} disabled={disabled || loading} aria-busy={loading || undefined}>
    {loading && <span className="ds-spinner" aria-hidden="true" />}{children}
  </button>;
}

import React from 'react';
import { Divider } from './divider.jsx';
// look matches the HTML data-look values; the media and row looks put a picture area before the body.
export function Card({ children, look = 'raised', ...props }) { return <article {...props} className="ds-card" data-look={look}>{(look === 'media' || look === 'row') && <div className="ds-card-media" aria-hidden="true" />}{children}</article>; }
export function CardBody({ children }) { return <div className="ds-card-body">{children}</div>; }
export function CardTitle({ children, as: Tag = 'h3' }) { return <Tag>{children}</Tag>; }
export function CardDescription({ children }) { return <p>{children}</p>; }
export function CardActions({ children }) { return <><Divider /><footer className="ds-card-actions">{children}</footer></>; }

